using Microsoft.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

public class TicketClassifierService
{
    private readonly MLContext _mlContext;
    private ITransformer? _model;
    private PredictionEngine<TicketData, TicketPrediction>? _predictionEngine;
    private string[] _categoryLabels = [];
    private readonly string _dataPath;
    private readonly string _modelPath;
    private readonly ILogger<TicketClassifierService> _logger;

    public bool IsTrained => _model is not null;

    public TicketClassifierService(ILogger<TicketClassifierService> logger, IWebHostEnvironment env)
    {
        _mlContext = new MLContext(seed: 42);
        _logger = logger;
        _dataPath = Path.Combine(env.ContentRootPath, "Data", "tickets.csv");
        _modelPath = Path.Combine(env.ContentRootPath, "Data", "model.zip");
    }

    /// <summary>
    /// Trains the model from the CSV and returns evaluation metrics.
    /// </summary>
    public EvaluationResponse TrainAndEvaluate()
    {
        _logger.LogInformation("Loading training data from {Path}", _dataPath);

        var dataView = _mlContext.Data.LoadFromTextFile<TicketData>(
            _dataPath, hasHeader: true, separatorChar: ',', allowQuoting: true);

        // Combine text features and build the classification pipeline
        var pipeline = _mlContext.Transforms.Conversion
            .MapValueToKey("Label", nameof(TicketData.Category))
            .Append(_mlContext.Transforms.Text.FeaturizeText("SubjectFeaturized", nameof(TicketData.Subject)))
            .Append(_mlContext.Transforms.Text.FeaturizeText("DescriptionFeaturized", nameof(TicketData.Description)))
            .Append(_mlContext.Transforms.Concatenate("Features",
                "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
            .Append(_mlContext.MulticlassClassification.Trainers.SdcaMaximumEntropy("Label", "Features"))
            .Append(_mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

        // With a small dataset, train on all data and evaluate via cross-validation
        _logger.LogInformation("Training model...");
        _model = pipeline.Fit(dataView);

        // Persist the trained model
        _mlContext.Model.Save(_model, dataView.Schema, _modelPath);
        _logger.LogInformation("Model saved to {Path}", _modelPath);

        // Build prediction engine and extract label ordering
        RebuildPredictionEngine(dataView.Schema);

        // Evaluate with cross-validation (gives meaningful metrics even on small data)
        var cvResults = _mlContext.MulticlassClassification
            .CrossValidate(dataView, pipeline, numberOfFolds: 3);

        var metrics = new EvaluationResponse
        {
            MacroAccuracy = cvResults.Average(r => r.Metrics.MacroAccuracy),
            MicroAccuracy = cvResults.Average(r => r.Metrics.MicroAccuracy),
            LogLoss = cvResults.Average(r => r.Metrics.LogLoss),
            LogLossReduction = cvResults.Average(r => r.Metrics.LogLossReduction)
        };

        _logger.LogInformation("Training complete — MacroAccuracy: {Acc:P2}", metrics.MacroAccuracy);
        return metrics;
    }

    /// <summary>
    /// Loads a previously saved model from disk.
    /// </summary>
    public void LoadModel()
    {
        if (!File.Exists(_modelPath))
            return;

        _model = _mlContext.Model.Load(_modelPath, out var schema);
        RebuildPredictionEngine(schema);
        _logger.LogInformation("Model loaded from {Path}", _modelPath);
    }

    /// <summary>
    /// Predicts the category for a support ticket.
    /// </summary>
    public PredictionResponse Predict(TicketRequest request)
    {
        if (_predictionEngine is null)
            throw new InvalidOperationException(
                "Model has not been trained. POST to /api/ticket/train first.");

        var ticketData = new TicketData
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority
        };

        var prediction = _predictionEngine.Predict(ticketData);

        var confidenceScores = new Dictionary<string, float>();
        for (var i = 0; i < _categoryLabels.Length; i++)
            confidenceScores[_categoryLabels[i]] = prediction.Score[i];

        return new PredictionResponse
        {
            PredictedCategory = prediction.PredictedCategory,
            ConfidenceScores = confidenceScores
        };
    }

    private void RebuildPredictionEngine(DataViewSchema schema)
    {
        _predictionEngine = _mlContext.Model
            .CreatePredictionEngine<TicketData, TicketPrediction>(_model, schema);

        // Extract the label names in score-array order
        var labelCol = _model!.GetOutputSchema(schema)["PredictedLabel"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        _model.GetOutputSchema(schema)["Score"]
            .GetSlotNames(ref slotNames);
        _categoryLabels = slotNames.DenseValues()
            .Select(v => v.ToString()).ToArray();
    }
}

